<template><SuperAdminLayout><main class="nar-page"><header class="nar-head"><h1>5. NEW ACCOUNTS – UNDER REVIEW</h1><div><small>Last Updated: <b>{{ formatDate(lastUpdated) }}</b></small><button class="nar-new" @click="router.push('/register')">＋ New Account</button></div></header><form class="nar-filters" @submit.prevent="load(1)"><div class="nar-filter-dates"><b>Filter By Sign Up Date:</b><label>From Date<input v-model="filters.from_date" type="date"></label><label>To Date<input v-model="filters.to_date" type="date"></label></div><label>Service Plan:<select v-model="filters.plan"><option value="all">All</option><option v-for="plan in plans" :key="plan" :value="plan.toLowerCase()">{{ plan }}</option></select></label><label>Payment Status:<select v-model="filters.payment_status"><option value="all">All</option><option value="paid">Paid</option><option value="unpaid">Unpaid</option></select></label><label>Search (Name, Email, Phone, ID):<input v-model="filters.search" placeholder="Search..."></label><div class="nar-filter-actions"><button>Search</button><button type="button" @click="clear">Clear</button></div></form><div class="nar-table-wrap"><table class="nar-table"><thead><tr><th>No.</th><th><i>NEW</i></th><th>Sign Up Date⌄</th><th>Account ID. Number</th><th>Customer Name</th><th>Phone No.</th><th>Email</th><th>Service Plan</th><th>Paid Now</th><th>Status</th><th>View Details</th><th>Action</th></tr></thead><tbody><tr v-for="(row,index) in accounts" :key="row.id"><td>{{ number(index) }}</td><td><i v-if="row.is_new">NEW</i></td><td>{{ formatDate(row.sign_up_date) }}</td><td>{{ row.account_number }}</td><td>{{ row.customer }}</td><td>{{ row.phone || '—' }}</td><td>{{ row.email }}</td><td>{{ row.plan }}</td><td>{{ currency(row.paid_now) }}</td><td><span class="nar-status">{{ row.status }}</span></td><td><button class="nar-detail" @click="router.push('/super-admin/customers/'+row.id)">View Details</button></td><td class="nar-actions"><button class="nar-approve" @click="approve(row)">✓ Approve</button><button class="nar-pending" type="button">◉ Pending</button></td></tr><tr v-if="!loading&&!accounts.length"><td colspan="12" class="nar-empty">No new accounts are currently under review.</td></tr></tbody></table></div><footer class="nar-footer"><strong>Total New Accounts: <span>{{ meta.total || 0 }}</span></strong><div><label>Show <select v-model.number="perPage" @change="load(1)"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select> per page</label><button :disabled="!meta.prev_page_url" @click="load(1)">|&lt;</button><button :disabled="!meta.prev_page_url" @click="load(meta.current_page-1)">&lt;</button><b>{{ meta.current_page || 1 }}</b><button :disabled="!meta.next_page_url" @click="load(meta.current_page+1)">&gt;</button><button :disabled="!meta.next_page_url" @click="load(meta.last_page)">&gt;|</button><span>Page {{ meta.current_page || 1 }} of {{ meta.last_page || 1 }}</span></div></footer></main></SuperAdminLayout></template>
<script setup>import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const router=useRouter(),today=new Date(),date=v=>new Date(v).toISOString().slice(0,10),defaults=()=>({from_date:date(new Date(today.getFullYear(),today.getMonth(),1)),to_date:date(today),plan:'all',payment_status:'all',search:''}),filters=ref(defaults()),accounts=ref([]),plans=ref([]),meta=ref({}),lastUpdated=ref(null),perPage=ref(10),loading=ref(false);const formatDate=v=>v?new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'—',currency=v=>Number(v||0).toLocaleString('en-US',{style:'currency',currency:'USD'}),number=i=>((meta.value.current_page||1)-1)*(meta.value.per_page||perPage.value)+i+1;async function load(page=1){loading.value=true;try{const{data}=await client.get('/super-admin/pending-accounts',{params:{...filters.value,per_page:perPage.value,page}}),result=data.data||{};accounts.value=result.accounts?.data||[];meta.value=result.accounts||{};plans.value=result.plans||[];lastUpdated.value=result.last_updated}finally{loading.value=false}}function clear(){filters.value=defaults();load(1)}async function approve(row){if(!confirm(`Approve ${row.customer}?`))return;await client.post(`/super-admin/pending-accounts/${row.id}/approve`);load(meta.value.current_page||1)}onMounted(()=>load())</script>
<style>
.nar-page{color:#07194c}.nar-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}.nar-head h1{font-size:2.52rem;font-weight:800;letter-spacing:-.04em;margin:4px 0}.nar-head>div{text-align:right}.nar-head small{display:block;margin:0 0 14px;font-size:.78rem}.nar-new,.nar-filter-actions button{border:1px solid #082b75;background:#082b75;color:#fff;border-radius:5px;font-weight:700;height:43px;padding:0 22px}.nar-filters{display:grid;grid-template-columns:2.1fr .9fr .9fr 1.2fr auto;gap:38px;align-items:end;padding:24px 22px 20px;border:1px solid #dbe3ee;border-radius:6px;background:#fff;margin-bottom:12px}.nar-filters label{display:grid;gap:8px;font-size:.8rem;font-weight:700}.nar-filters input,.nar-filters select{height:46px;border:1px solid #d2dbe8;border-radius:5px;padding:0 12px;background:#fff;font:inherit;color:#17203c}.nar-filter-dates{display:grid;grid-template-columns:1fr 1fr;gap:12px}.nar-filter-dates>b{grid-column:1/-1;font-size:.82rem}.nar-filter-actions{display:flex;gap:14px}.nar-filter-actions button+button{background:#fff;color:#07194c;border-color:#aebbd1}.nar-table-wrap{overflow:auto;border:1px solid #dce4ef;border-radius:6px}.nar-table{width:100%;min-width:1450px;border-collapse:collapse;font-size:.77rem;background:#fff}.nar-table th{height:48px;background:linear-gradient(100deg,#031b51,#062d76);color:#fff!important;text-align:center;white-space:nowrap;padding:7px}.nar-table td{padding:11px 8px;text-align:center;border:1px solid #e6ebf2;white-space:nowrap}.nar-table i{display:inline-block;background:#f3272d;color:#fff;font-style:normal;font-size:.65rem;font-weight:800;border-radius:3px;padding:4px 6px}.nar-status{display:inline-block;background:#fff0c6;color:#5d4500;border-radius:14px;padding:5px 10px;font-size:.7rem}.nar-detail,.nar-approve,.nar-pending{border:1px solid #c5d0e1;background:#fff;color:#08276c;border-radius:4px;padding:6px 10px;font-weight:700;font-size:.71rem}.nar-approve{border-color:#46bb7e;color:#067331}.nar-pending{color:#536073;background:#f8fafc;margin-left:5px}.nar-empty{height:100px;color:#718096}.nar-footer{display:flex;justify-content:space-between;align-items:center;padding:10px 24px;border:1px solid #dfe6ef;background:#f8faff;border-radius:6px;margin-top:0}.nar-footer strong{font-size:1rem}.nar-footer strong span{margin-left:12px}.nar-footer>div{display:flex;align-items:center;gap:10px;font-size:.78rem}.nar-footer label{display:flex;align-items:center;gap:8px}.nar-footer select,.nar-footer button{height:36px;border:1px solid #d7e0ec;background:#fff;border-radius:4px;padding:0 10px}.nar-footer b{background:#073685;color:#fff;padding:10px 14px;border-radius:4px}@media(max-width:1200px){.nar-filters{gap:15px}.nar-head{display:block}.nar-head>div{text-align:left;margin-top:14px}}@media(max-width:760px){.nar-head h1{font-size:1.8rem}.nar-filters{grid-template-columns:1fr}.nar-footer{align-items:flex-start;flex-direction:column;gap:12px}.nar-footer>div{flex-wrap:wrap}}
</style>
